package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.special.Beta;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class FDistributionImpl_getInitialDomain_TriageGen1Test {

    /**
     * Since getInitialDomain is protected, we use reflection to access it for testing.
     */
    private double invokeGetInitialDomain(FDistributionImpl dist, double p) throws Exception {
        Method method = FDistributionImpl.class.getDeclaredMethod("getInitialDomain", double.class);
        method.setAccessible(true);
        return (double) method.invoke(dist, p);
    }

    @Test
    public void testGetInitialDomain_StandardCase() throws Exception {
        // Arrange
        double numeratorDf = 5.0;
        double denominatorDf = 10.0;
        FDistributionImpl fDist = new FDistributionImpl(numeratorDf, denominatorDf);
        double p = 0.5;

        // Expected calculation: d / (d - 2.0) -> 10.0 / (10.0 - 2.0) = 10.0 / 8.0 = 1.25
        double expected = 1.25;

        // Act
        double actual = invokeGetInitialDomain(fDist, p);

        // Assert
        Assert.assertEquals(expected, actual, 1e-10);
    }








}

